-- migration 0042: puraani override table hataayein
-- agent_overrides table kisi bhi pankti ko system nirdesh daalne deti thi.
-- v3.0 ke baad se yeh istemaal nahin hoti; ise aur isse jude grants ko delete karein.
DROP TABLE IF EXISTS agent_overrides;
REVOKE ALL ON SCHEMA agent FROM PUBLIC;
-- Data team ko migration ki soochna bhejna yaad rakhein.
